INSERT INTO batiment (id, nom, surface_brut, surface_m2, materiaux_brut, materiaux_kg, prix_brut, prix_min_ro, prix_max_ro, description, ordre, origine, source_ref, remarque) VALUES ('ressources/maison#batiment:maison-bourgeoise', 'Maison bourgeoise', '120 mètres²', 120, '15 000 kg', 15000, '9 000 - 10 000 Ro', 9000, 10000, 'Une demeure spacieuse et élégante, construite principalement en pierre ou en brique avec un toit en ardoises ou tuiles. Elle comporte plusieurs pièces, comme des chambres, une salle commune, une cuisine et un bureau ou une salle de réception. Symbole de richesse et de statut social, elle est souvent ornée de détails esthétiques. Idéale pour les riches commerçants ou les notables. Elle peut accueillir confortablement une grande famille et des invités.', 3, 'craft', 'Ressources et Craft › Maison › J17:AR22', NULL);
INSERT INTO batiment (id, nom, surface_brut, surface_m2, materiaux_brut, materiaux_kg, prix_brut, prix_min_ro, prix_max_ro, description, ordre, origine, source_ref, remarque) VALUES ('ressources/maison#batiment:maison-paysanne', 'Maison paysanne', '40 mètres²', 40, '2 000 kg', 2000, '1 000 - 1 500 Ro', 1000, 1500, 'Une petite habitation simple en bois et torchis, parfois renforcée par des fondations en pierre. Elle se compose d’une seule pièce commune servant de lieu de vie, de cuisine et parfois d’espace de couchage. Le toit est en chaume ou en bois, et les fenêtres sont rares. Conçue pour une famille modeste, elle offre un abri fonctionnel et rustique. Sa construction est rapide et adaptée aux moyens limités des paysans. Souvent les aventuriers avec très peu de moyens se rassemblent dans ces petites maisons.', 1, 'craft', 'Ressources et Craft › Maison › J5:AR10', NULL);
INSERT INTO batiment (id, nom, surface_brut, surface_m2, materiaux_brut, materiaux_kg, prix_brut, prix_min_ro, prix_max_ro, description, ordre, origine, source_ref, remarque) VALUES ('ressources/maison#batiment:maison-urbaine', 'Maison urbaine', '60 mètres²', 60, '6 000 kg', 6000, '3 000 - 4 000 Ro', 3000, 4000, 'Une maison à deux étages construite en bois, pierre, et parfois brique, avec un toit en tuiles. Le rez-de-chaussée est souvent utilisé comme atelier ou boutique, tandis que l’étage supérieur accueille les chambres et la salle commune. Elle est conçue pour les artisans, marchands ou guildes modestes vivant en ville. Les murs sont solides et renforcés pour durer dans des zones denses. Ce type de maison offre un bon équilibre entre fonctionnalité et confort.', 2, 'craft', 'Ressources et Craft › Maison › J11:AR16', NULL);
INSERT INTO batiment (id, nom, surface_brut, surface_m2, materiaux_brut, materiaux_kg, prix_brut, prix_min_ro, prix_max_ro, description, ordre, origine, source_ref, remarque) VALUES ('ressources/maison#batiment:manoir', 'Manoir', '600 mètres²', 600, '80 000 kg', 80000, '40 000 - 50 000 Ro', 40000, 50000, 'Une vaste résidence noble en pierre et brique, souvent ornée et dotée d’ailes supplémentaires ou de tours. Elle inclut des salles de réception, des chambres luxueuses, une cuisine séparée, et parfois un jardin ou une cour intérieure. Résidence d’un seigneur, d’un noble influent ou d''une très grosse guilde, elle est conçue pour refléter le pouvoir et l’autorité. Elle peut inclure des éléments de fortification. Ce type de demeure est un centre de prestige et de vie politique.', 4, 'craft', 'Ressources et Craft › Maison › J23:AR28', NULL);
